// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/// Why a permutation-group operation refused.
///
/// Every variant is a refusal, never a degraded answer: this module has no
/// "best effort" path. See the module docs for the standing scope limits that
/// produce [`GroupError::DegreeTooLargeForBsgs`] and
/// [`GroupError::EnumerationTooLarge`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum GroupError {
    /// An images array is not a bijection of `{0, …, n−1}`: some entry is out
    /// of range, or two points share an image.
    NotAPermutation {
        /// The degree the array claimed.
        degree: usize,
        /// What is wrong, concretely.
        reason: String,
    },
    /// Two permutations, or a permutation and a group, disagree on the degree.
    ///
    /// Degrees are **not** silently widened by padding with fixed points. `S_3`
    /// embedded in `S_5` is a different subgroup of a different symmetric group
    /// from `S_3` itself, and which one a caller meant is not recoverable from
    /// the arguments; use [`Permutation::extend_degree`] to say so explicitly.
    DegreeMismatch {
        /// Degree of the left/receiving operand.
        left: usize,
        /// Degree of the right/supplied operand.
        right: usize,
    },
    /// A point outside `{0, …, n−1}` was named.
    PointOutOfRange {
        /// The offending point.
        point: usize,
        /// The degree it had to be below.
        degree: usize,
    },
    /// The group is too large to enumerate element by element.
    ///
    /// The order is still available from [`PermutationGroup::order`]; it is the
    /// *list* that is refused.
    EnumerationTooLarge {
        /// Decimal rendering of `|G|` (it may not fit a `u64`).
        order: String,
        /// The cap that was in force.
        cap: u64,
    },
    /// The degree exceeds [`MAX_BSGS_DEGREE`], above which the explicit
    /// transversals this chain stores would exhaust memory.
    DegreeTooLargeForBsgs {
        /// The degree asked for.
        degree: usize,
        /// The largest degree this implementation accepts.
        max: usize,
    },
    /// A standard constructor was called outside the range where its degree-`n`
    /// action is defined and faithful.
    UnsupportedDegree {
        /// Which family: `"symmetric"`, `"dihedral"`, …
        family: &'static str,
        /// The `n` that was asked for.
        requested: usize,
        /// Why that `n` has no such group in this representation.
        reason: &'static str,
    },
}

impl fmt::Display for GroupError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            GroupError::NotAPermutation { degree, reason } => write!(
                f,
                "not a permutation of {{0, …, {}}}: {reason}",
                degree.saturating_sub(1)
            ),
            GroupError::DegreeMismatch { left, right } => write!(
                f,
                "permutation degrees disagree: {left} and {right}. Degrees are not padded \
                 automatically; use `Permutation::extend_degree` to embed the smaller one"
            ),
            GroupError::PointOutOfRange { point, degree } => write!(
                f,
                "point {point} is outside {{0, …, {}}} (degree {degree}); note that points \
                 are 0-based here",
                degree.saturating_sub(1)
            ),
            GroupError::EnumerationTooLarge { order, cap } => write!(
                f,
                "the group has order {order}, above the enumeration cap of {cap}; its order \
                 is known exactly but its elements will not be listed"
            ),
            GroupError::DegreeTooLargeForBsgs { degree, max } => write!(
                f,
                "degree {degree} exceeds the Schreier–Sims limit of {max}: this chain stores \
                 an explicit transversal permutation per orbit point"
            ),
            GroupError::UnsupportedDegree {
                family,
                requested,
                reason,
            } => write!(f, "{family}({requested}) is not available: {reason}"),
        }
    }
}

impl std::error::Error for GroupError {}

impl crate::errors::AlkahestError for GroupError {
    fn code(&self) -> &'static str {
        match self {
            GroupError::NotAPermutation { .. } => "E-GRP-001",
            GroupError::DegreeMismatch { .. } => "E-GRP-002",
            GroupError::PointOutOfRange { .. } => "E-GRP-003",
            GroupError::EnumerationTooLarge { .. } => "E-GRP-004",
            GroupError::DegreeTooLargeForBsgs { .. } => "E-GRP-005",
            GroupError::UnsupportedDegree { .. } => "E-GRP-006",
        }
    }

    fn remediation(&self) -> Option<&'static str> {
        match self {
            GroupError::NotAPermutation { .. } => Some(
                "supply each of 0..n exactly once as an image; points are 0-based, so a cycle \
                 copied from GAP or the ATLAS needs `Permutation::from_cycles_one_based`",
            ),
            GroupError::DegreeMismatch { .. } => Some(
                "embed the smaller permutation with `Permutation::extend_degree(n)` before \
                 composing, or rebuild both at the common degree",
            ),
            GroupError::PointOutOfRange { .. } => {
                Some("points are 0-based: the valid range is 0..degree")
            }
            GroupError::EnumerationTooLarge { .. } => Some(
                "use `order()`, `contains()` or `random_element()` instead of listing the \
                 elements, or raise the cap with `elements_with_cap` if the list really fits \
                 in memory",
            ),
            GroupError::DegreeTooLargeForBsgs { .. } => Some(
                "orbits and orbit representatives are available at any degree; only the \
                 stabilizer chain (and therefore `order`, `contains` and `elements`) is capped",
            ),
            GroupError::UnsupportedDegree { .. } => Some(
                "these constructors build the natural degree-n action; below the stated \
                 minimum that action is not faithful, so build the group by hand on the \
                 point set you actually mean",
            ),
        }
    }
}
